   [73]={next_id=74, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="You think I didn't claw my way up? That anyone can sweet-talk their way to the top like you nobles?", msg_color="", msg_size=0, talker="Rosana", audio="", img="arts/ui/bg/story/storybg_903.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "7153", 2, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
